arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var rawData = mlContext.Data.LoadFromTextFile<RawCustomerData>(dataPath, separatorChar: ',', hasHeader: true);

// Map "Yes"/"No" → true/false using a serializable ValueMapping transform
var labelKeys = new[] { "Yes", "No" };
var labelValues = new[] { true, false };
var pipeline = mlContext.Transforms.Conversion.MapValue(
        "Label", new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false },
        inputColumnName: nameof(RawCustomerData.Churned))
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(RawCustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(RawCustomerData.Age), nameof(RawCustomerData.Income),
        "RegionEncoded", nameof(RawCustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var rowCount = (int)rawData.GetColumn<float>(nameof(RawCustomerData.Age)).LongCount();

ITransformer model;
if (rowCount >= 20)
{
    var split = mlContext.Data.TrainTestSplit(rawData, testFraction: 0.2);
    model = pipeline.Fit(split.TrainSet);
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"Model Accuracy: {metrics.Accuracy:F4}, AUC: {metrics.AreaUnderRocCurve:F4}, F1: {metrics.F1Score:F4}");
}
else
{
    model = pipeline.Fit(rawData);
    var predictions = model.Transform(rawData);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    Console.WriteLine($"[Small dataset — no held-out test set] Accuracy: {metrics.Accuracy:F4}, AUC: {metrics.AreaUnderRocCurve:F4}, F1: {metrics.F1Score:F4}");
}

// Save and register the pooled prediction engine (thread-safe)
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
mlContext.Model.Save(model, rawData.Schema, modelPath);

builder.Services.AddPredictionEnginePool<RawCustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with customer data.");

app.MapPost("/predict", (PredictionEnginePool<RawCustomerData, ChurnPrediction> pool, CustomerRequest req) =>
{
    var input = new RawCustomerData
    {
        Age = req.Age,
        Income = req.Income,
        Region = req.Region,
        PurchaseHistory = req.PurchaseHistory,
        Churned = string.Empty
    };
    var result = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = result.PredictedLabel,
        Probability = result.Probability,
        Score = result.Score
    });
});

app.Run();

// --- Data models ---

public class RawCustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

public record CustomerRequest(float Age, float Income, string Region, float PurchaseHistory);

arguments.old_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
var rawData = mlContext.Data.LoadFromTextFile<RawCustomerData>(dataPath, separatorChar: ',', hasHeader: true);

// Map "Yes"/"No" string to boolean Label column
var pipeline = mlContext.Transforms.CustomMapping<RawCustomerData, LabelMapped>(
        (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
        contractName: "ChurnLabelMapping")
    .Append(mlContext.Transforms.CopyColumns("Age", nameof(RawCustomerData.Age)))
    .Append(mlContext.Transforms.CopyColumns("Income", nameof(RawCustomerData.Income)))
    .Append(mlContext.Transforms.CopyColumns("Region", nameof(RawCustomerData.Region)))
    .Append(mlContext.Transforms.CopyColumns("PurchaseHistory", nameof(RawCustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
    .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "RegionEncoded", "PurchaseHistory"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label",
        featureColumnName: "Features"));

var rowCount = (int)rawData.GetColumn<float>("Age").LongCount();

ITransformer model;
if (rowCount >= 20)
{
    // Enough data for a proper train/test split
    var split = mlContext.Data.TrainTestSplit(rawData, testFraction: 0.2);
    model = pipeline.Fit(split.TrainSet);
